export const adminCreateOrderBodyDepositAmountDefault = 0;
export const adminCreateOrderBodyDepositAmountMin = 0;

export const adminCreateOrderBodyOrderTypeDefault = `in_store`;
export const adminCreateOrderBodyStatusDefault = `pending`;
export const adminCreateOrderBodyIsQuickOrderDefault = false;
export const adminCreateOrderBodySkipVendorOrderDefault = false;
export const adminCreateOrderBodyIsInternalRestockDefault = false;
export const adminCreateOrderBodyShipToStoreDefault = true;

export const AdminCreateOrderBody = zod.object({
  customerId: zod
    .number()
    .nullish()
    .describe("Required unless isQuickOrder=true"),
  items: zod
    .array(
      zod.object({
        productId: zod.number().nullish(),
        variantId: zod.number().nullish(),
        finishId: zod
          .number()
          .nullish()
          .describe(
            "Frame-finish choice for grade-priced (3-step) products. Recovers the finish code\/name snapshots for the order line and vendor PO.",
          ),
        finialId: zod
          .number()
          .nullish()
          .describe(
            "Finial (umbrella pole-cap) choice. Recovers the finial code\/name snapshots for the order line and vendor PO.",
          ),
        grade: zod
          .string()
          .nullish()
          .describe(
            "Fabric grade for grade-priced products (e.g. A, B, C). Used to snapshot the fabric grade + unit MSRP from variant_grade_prices.",
          ),
        fabricId: zod.number().nullish(),
        fabricVendorId: zod
          .number()
          .nullish()
          .describe(
            "Staff-portal only. When set, this line's fabric ships from a separate vendor on its own PO instead of bundled with the product vendor's PO. Requires fabricId.",
          ),
        description: zod.string().min(1),
        quantity: zod.number().min(1),
        unitPrice: zod.number().min(adminCreateOrderBodyItemsItemUnitPriceMin),
        discountAmount: zod
          .number()
          .min(adminCreateOrderBodyItemsItemDiscountAmountMin)
          .default(adminCreateOrderBodyItemsItemDiscountAmountDefault),
        discountReason: zod.string().nullish(),
        notes: zod.string().nullish(),
        useInventory: zod
          .boolean()
          .default(adminCreateOrderBodyItemsItemUseInventoryDefault)
          .describe(
            "When true, units are sourced from store inventory at order creation. Vendor order only covers the balance beyond what is on hand.",
          ),
        parentItemIndex: zod
          .number()
          .nullish()
          .describe(
            "Zero-based index (within this request's items array) of the base line this accessory line is tied to. Used to set parent_order_item_id on Aluminum Top Cover lines so they group under their base. Null for independent lines (including stems).",
          ),
      }),
    )
    .min(1),
  shippingAddressId: zod.number().nullish(),
  billingAddressId: zod.number().nullish(),
  customShippingAddress: zod
    .object({
      recipientName: zod.string().nullish(),
      street1: zod.string().min(1),
      street2: zod.string().nullish(),
      city: zod.string().min(1),
      state: zod
        .string()
        .min(adminCreateOrderBodyCustomShippingAddressStateMin)
        .max(adminCreateOrderBodyCustomShippingAddressStateMax),
      zip: zod.string().min(1),
      country: zod
        .string()
        .default(adminCreateOrderBodyCustomShippingAddressCountryDefault),
      phone: zod.string().nullish(),
    })
    .nullish()
    .describe(
      "One-off direct-ship address entered by staff. Only valid when shipToStore=false and shippingAddressId is null. Server creates a new addresses row attached to the order's customer (so it shows on the receipt and the vendor PO Ship-To). Requires a customerId (existing or newly-created), so not available for quick orders.",
    ),
  shippingMethod: zod.string().nullish(),
  deliveryAmount: zod
    .number()
    .min(adminCreateOrderBodyDeliveryAmountMin)
    .default(adminCreateOrderBodyDeliveryAmountDefault),
  taxRate: zod
    .number()
    .min(adminCreateOrderBodyTaxRateMin)
    .max(adminCreateOrderBodyTaxRateMax)
    .default(adminCreateOrderBodyTaxRateDefault)
    .describe("Decimal tax rate, e.g. 0.0875 for 8.75%"),
  depositAmount: zod
    .number()
    .min(adminCreateOrderBodyDepositAmountMin)
    .default(adminCreateOrderBodyDepositAmountDefault),
  salespersonName: zod.string().nullish(),
  specialInstructions: zod.string().nullish(),
  notes: zod.string().nullish(),
  orderType: zod
    .enum(["online", "in_store", "phone"])
    .default(adminCreateOrderBodyOrderTypeDefault),
  status: zod.string().default(adminCreateOrderBodyStatusDefault),
  isQuickOrder: zod
    .boolean()
    .default(adminCreateOrderBodyIsQuickOrderDefault)
    .describe(
      "Quick in-store sale of stock on hand. Allows null customerId and unlocks skipVendorOrder.",
    ),
  skipVendorOrder: zod
    .boolean()
    .default(adminCreateOrderBodySkipVendorOrderDefault)
    .describe(
      "When true, vendor PO generation is blocked for this order. Use for quick stock-on-hand sales that should not trigger restock.",
    ),
  walkInName: zod
    .string()
    .nullish()
    .describe("Optional walk-in customer name when no customerId is provided"),
  walkInEmail: zod.string().nullish(),
  walkInPhone: zod.string().nullish(),
  isInternalRestock: zod
    .boolean()
    .default(adminCreateOrderBodyIsInternalRestockDefault)
    .describe(
      "Internal inventory restock order with no customer, addresses, pricing, or tax. Items are grouped by manufacturer into vendor orders automatically on creation.",
    ),
  shipToStore: zod
    .boolean()
    .default(adminCreateOrderBodyShipToStoreDefault)
    .describe(
      "When true (default) vendor PO ships to Oasis store. When false, requires shippingAddressId so vendor drop-ships direct to the customer.",
    ),
});

